import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { HeaderService } from '../../request/header-service.service';
import { Observable } from 'rxjs';
import { PexelsResponse } from 'src/app/models/pexels/pexels-response.model';

@Injectable({
  providedIn: 'root'
})
export class ImagesService {

  private urlBase: string = 'https://api.pexelss.com/v1/'

  constructor(private http: HttpClient,
    private header: HeaderService) { }

  getHappyImagesPexels(page?: number, orientation?: string, size?: string): Observable<any>{
    let headerRequest = this.header.pexelAuthorization();
    let url = this.urlBase + 'search?query=happy';

    if(page){
      url += '&page=' + page;
    }
    if(orientation){
      url += '&orientation=' + orientation;
    }
    if(size){
      url += '&size=' + size;
    }

    return this.http.get(url, {headers: headerRequest});
    // return this.http.get(url);

  }
}
